/**
 * MiniMax Chat Model Node - Version 1.1
 * For advanced usage with an AI chain
 */


export interface LcLmChatMinimaxV11Params {
/**
 * The model which will generate the completion. &lt;a href="https://platform.minimax.io/docs/api-reference/text-openai-api"&gt;Learn more&lt;/a&gt;.
 * @builderHint Choose a model from this node version's supported options. Keep a working or explicitly requested model unless provider evidence shows it is unavailable or unsuitable. When choosing a new model, select a current stable model supported by this node version, the configured API, and the required operation. Use the declared model-list lookup with the connected credential when available. Gateway credits can restrict that list. For a new choice without credentials, use current provider catalog information. Choose a model that fits the task and budget. Copy the exact model ID. Do not rely on node defaults, invent model IDs, or treat an unfamiliar model as invalid.
 * @default MiniMax-M3
 */
    model?: 'MiniMax-M2' | 'MiniMax-M2.1' | 'MiniMax-M2.1-highspeed' | 'MiniMax-M2.5' | 'MiniMax-M2.5-highspeed' | 'MiniMax-M2.7' | 'MiniMax-M2.7-highspeed' | 'MiniMax-M3' | Expression<string>;
/**
 * Additional options to add
 * @default {}
 */
    options?: {
    /** Whether to strip chain-of-thought reasoning from the response, returning only the final answer
     * @default true
     */
    hideThinking?: boolean | Expression<boolean>;
    /** The maximum number of tokens to generate in the completion. The limit depends on the selected model.
     * @default -1
     */
    maxTokens?: number | Expression<number>;
    /** Controls randomness: Lowering results in less random completions. As the temperature approaches zero, the model will become deterministic and repetitive.
     * @default 0.7
     */
    temperature?: number | Expression<number>;
    /** Maximum amount of time a request is allowed to take in milliseconds
     * @default 360000
     */
    timeout?: number | Expression<number>;
    /** Maximum number of retries to attempt
     * @default 2
     */
    maxRetries?: number | Expression<number>;
    /** Controls diversity via nucleus sampling: 0.5 means half of all likelihood-weighted options are considered. We generally recommend altering this or temperature but not both.
     * @default 1
     */
    topP?: number | Expression<number>;
  };
}

export interface LcLmChatMinimaxV11Credentials {
  minimaxApi: CredentialReference;
}

